import { Capacitor } from '@capacitor/core';
import { SpeechRecognition } from '@capgo/capacitor-speech-recognition';
import { TextToSpeech } from '@capacitor-community/text-to-speech';

export async function startNativeListening(onResult: (text: string) => void): Promise<void> {
  if (!Capacitor.isNativePlatform()) {
    throw new Error('Native voice bridge is only available on native platforms.');
  }

  const { speechRecognition } = await SpeechRecognition.requestPermissions();
  if (speechRecognition !== 'granted') throw new Error('Microphone permission denied');

  await SpeechRecognition.start({ language: 'en-US', maxResults: 1, partialResults: true, popup: false });

  await SpeechRecognition.addListener('partialResults', (data: { matches?: string[] }) => {
    if (data.matches?.[0]) onResult(data.matches[0]);
  });
}

export async function stopNativeListening(): Promise<void> {
  if (!Capacitor.isNativePlatform()) return;
  await SpeechRecognition.stop();
  await SpeechRecognition.removeAllListeners();
}

export async function speakNative(text: string): Promise<void> {
  if (!Capacitor.isNativePlatform()) {
    throw new Error('Native voice bridge is only available on native platforms.');
  }
  await TextToSpeech.speak({ text, lang: 'en-US', rate: 0.9, pitch: 1.0, volume: 1.0 });
}

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router';
import { Capacitor } from '@capacitor/core';
import { startNativeListening, stopNativeListening, speakNative } from '@/react-app/platform/voiceBridge';

export type VoiceStatus = 'idle' | 'listening' | 'processing' | 'speaking' | 'error';

interface VoiceIntegrationState {
  isVoiceActive: boolean;
  voiceStatus: VoiceStatus;
  cognitiveMode: boolean;
  lastCommand: string;
  edgeColor: string;
  edgeIntensity: number;
}

export const useVoiceIntegration = () => {
  const navigate = useNavigate();

  const [state, setState] = useState<VoiceIntegrationState>({
    isVoiceActive: false,
    voiceStatus: 'idle',
    cognitiveMode: false,
    lastCommand: '',
    edgeColor: '#10B981',
    edgeIntensity: 0.3
  });

  useEffect(() => {
    const getEdgeColor = () => {
      switch (state.voiceStatus) {
        case 'listening': return '#14B8A6';
        case 'processing': return '#3B82F6';
        case 'speaking': return '#8B5CF6';
        case 'error': return '#EF4444';
        default: return '#10B981';
      }
    };

    const getEdgeIntensity = () => {
      switch (state.voiceStatus) {
        case 'listening': return 0.8;
        case 'processing': return 0.9;
        case 'speaking': return 1.0;
        case 'error': return 0.7;
        default: return state.isVoiceActive ? 0.5 : 0.3;
      }
    };

    setState(prev => ({
      ...prev,
      edgeColor: getEdgeColor(),
      edgeIntensity: getEdgeIntensity()
    }));
  }, [state.voiceStatus, state.isVoiceActive]);

  const handleVoiceCommand = useCallback((command: string) => {
    setState(prev => ({ ...prev, lastCommand: command, voiceStatus: 'processing' }));

    const lowerCommand = command.toLowerCase();

    if (lowerCommand.includes('badges') || lowerCommand.includes('badge')) {
      navigate('/badges');
    } else if (lowerCommand.includes('vault')) {
      navigate('/vault');
    } else if (lowerCommand.includes('udc') || lowerCommand.includes('certificate')) {
      navigate('/udc');
    } else if (lowerCommand.includes('scan') || lowerCommand.includes('scanner')) {
      navigate('/scanner');
    } else if (lowerCommand.includes('workflow')) {
      navigate('/workflows');
    } else if (lowerCommand.includes('home') || lowerCommand.includes('verifier') || lowerCommand.includes('node')) {
      navigate('/dves');
    } else if (lowerCommand.includes('cognitive mode') || lowerCommand.includes('advanced mode')) {
      setState(prev => ({ ...prev, cognitiveMode: !prev.cognitiveMode }));
    } else if (lowerCommand.includes('balance') || lowerCommand.includes('how much')) {
       console.log('Checking balance...');
    } else if (lowerCommand.includes('send') || lowerCommand.includes('transfer')) {
       navigate('/vault');
       console.log('Initiating transfer...');
    } else if (lowerCommand.includes('activate') && lowerCommand.includes('badge')) {
      console.log('Badge activation requested:', command);
    } else if (lowerCommand.includes('deactivate') && lowerCommand.includes('badge')) {
      console.log('Badge deactivation requested:', command);
    } else if (lowerCommand.includes('check workflow') || lowerCommand.includes('workflow status')) {
      console.log('Workflow status check requested');
    } else if (lowerCommand.includes('deploy workflow')) {
      console.log('Workflow deployment requested');
    } else if (lowerCommand.includes('status') || lowerCommand.includes('health')) {
      console.log('System status check requested');
    }

    setTimeout(() => {
      setState(prev => ({ ...prev, voiceStatus: 'speaking' }));
      setTimeout(() => {
        setState(prev => ({ ...prev, voiceStatus: 'idle' }));
      }, 1000);
    }, 800);
  }, [navigate]);

  const toggleVoice = useCallback(async (active: boolean) => {
    setState(prev => ({
      ...prev,
      isVoiceActive: active,
      voiceStatus: active ? 'listening' : 'idle'
    }));

    if (Capacitor.isNativePlatform()) {
      if (active) {
        try {
          await startNativeListening(handleVoiceCommand);
        } catch (err) {
          console.error('Failed to start native voice:', err);
          setState(prev => ({ ...prev, isVoiceActive: false, voiceStatus: 'error' }));
        }
      } else {
        await stopNativeListening();
      }
    }
  }, [handleVoiceCommand]);

  const toggleCognitiveMode = useCallback(() => {
    setState(prev => ({ ...prev, cognitiveMode: !prev.cognitiveMode }));
  }, []);

  const setVoiceStatus = useCallback((status: VoiceStatus) => {
    setState(prev => ({ ...prev, voiceStatus: status }));
  }, []);

  const speakResponse = useCallback(async (text: string) => {
    setState(prev => ({ ...prev, voiceStatus: 'speaking' }));

    if (Capacitor.isNativePlatform()) {
      try {
        await speakNative(text);
      } catch (err) {
        console.error('Failed to speak native:', err);
      }
      setState(prev => ({ ...prev, voiceStatus: 'idle' }));
      return;
    }

    const duration = Math.max(2000, text.length * 50);
    setTimeout(() => {
      setState(prev => ({ ...prev, voiceStatus: 'idle' }));
    }, duration);
  }, []);

  return {
    isVoiceActive: state.isVoiceActive,
    voiceStatus: state.voiceStatus,
    cognitiveMode: state.cognitiveMode,
    lastCommand: state.lastCommand,
    edgeColor: state.edgeColor,
    edgeIntensity: state.edgeIntensity,
    handleVoiceCommand,
    toggleVoice,
    toggleCognitiveMode,
    setVoiceStatus,
    speakResponse
  };
};

import { Capacitor } from '@capacitor/core';
import { Preferences } from '@capacitor/preferences';

export const nativeStorage = {
  async get(key: string): Promise<string | null> {
    if (Capacitor.isNativePlatform()) {
      const { value } = await Preferences.get({ key });
      return value ?? null;
    }
    return localStorage.getItem(key);
  },

  async set(key: string, value: string): Promise<void> {
    if (Capacitor.isNativePlatform()) {
      await Preferences.set({ key, value });
    } else {
      localStorage.setItem(key, value);
    }
  },

  async remove(key: string): Promise<void> {
    if (Capacitor.isNativePlatform()) {
      await Preferences.remove({ key });
    } else {
      localStorage.removeItem(key);
    }
  },
};

import { useState, useEffect, useCallback } from 'react';
import { nativeStorage } from '@/react-app/platform/nativeStorage';
import { DVEVault } from '@/shared/types';
import { getVaultSession, updateVaultSession, type VaultStatus } from './vaultSession';

const VAULT_STORAGE_KEY = 'knirv_vault';
const DVE_DERIVATION_BASE_PATH = "m/44'/60'/1'/0/";

export const useVault = () => {
  const vaultSession = getVaultSession();
  const [vault, setVault] = useState<any | null>(() => vaultSession.vault);
  const [status, setStatus] = useState<VaultStatus>(() => vaultSession.status);
  const [accounts, setAccounts] = useState<any[]>(() => vaultSession.accounts);
  const [currentAccount, setCurrentAccount] = useState<any | null>(() => vaultSession.currentAccount);
  const [dveVaults, setDVEVaults] = useState<DVEVault[]>(() => vaultSession.dveVaults);
  const [error, setError] = useState<string | null>(() => vaultSession.error);

  useEffect(() => {
    const checkStorage = async () => {
      const currentSession = getVaultSession();
      if (currentSession.status !== 'initializing') {
        setVault(currentSession.vault);
        setStatus(currentSession.status);
        setAccounts(currentSession.accounts);
        setCurrentAccount(currentSession.currentAccount);
        setDVEVaults(currentSession.dveVaults);
        setError(currentSession.error);
        return;
      }
      const storedVault = await nativeStorage.get(VAULT_STORAGE_KEY);
      if (storedVault) {
        setStatus('locked');
      } else {
        setStatus('no_vault');
      }
    };
    checkStorage();
  }, []);

  useEffect(() => {
    if (vault) {
      setAccounts(vault.accounts || []);
      setCurrentAccount(vault.currentAccount || null);
    }
  }, [vault]);

  const createVault = useCallback(async (password: string): Promise<string> => {
    try {
      setStatus('initializing');
      const { KnirvWallet } = await import('knirvwallet-module/wallet');
      const mnemonic = KnirvWallet.generateMnemonic(12);
      const newVault = await KnirvWallet.createByMnemonic(mnemonic);
      const serialized = await newVault.serialize(password);
      await nativeStorage.set(VAULT_STORAGE_KEY, serialized);
      setVault(newVault);
      updateVaultSession({
        vault: newVault, status: 'unlocked', accounts: newVault.accounts || [],
        currentAccount: newVault.currentAccount || null, dveVaults: [], error: null,
      });
      setStatus('unlocked');
      return mnemonic;
    } catch (err: any) {
      console.error('Failed to create vault:', err);
      setError(err.message || 'Failed to create vault');
      updateVaultSession({ error: err.message || 'Failed to create vault' });
      setStatus('no_vault');
      throw err;
    }
  }, []);

  const importVault = useCallback(async (mnemonic: string, password: string) => {
    try {
      setStatus('initializing');
      const { KnirvWallet } = await import('knirvwallet-module/wallet');
      const newVault = await KnirvWallet.createByMnemonic(mnemonic);
      const serialized = await newVault.serialize(password);
      await nativeStorage.set(VAULT_STORAGE_KEY, serialized);
      setVault(newVault);
      updateVaultSession({
        vault: newVault, status: 'unlocked', accounts: newVault.accounts || [],
        currentAccount: newVault.currentAccount || null, dveVaults: [], error: null,
      });
      setStatus('unlocked');
    } catch (err: any) {
      console.error('Failed to import vault:', err);
      setError(err.message || 'Failed to import vault');
      updateVaultSession({ error: err.message || 'Failed to import vault' });
      setStatus('no_vault');
      throw err;
    }
  }, []);

  const unlockVault = useCallback(async (password: string) => {
    try {
      setStatus('initializing');
      const storedVault = await nativeStorage.get(VAULT_STORAGE_KEY);
      if (!storedVault) { throw new Error('No vault found'); }
      const { KnirvWallet } = await import('knirvwallet-module/wallet');
      const unlockedVault = await KnirvWallet.deserialize(storedVault, password);
      setVault(unlockedVault);
      updateVaultSession({
        vault: unlockedVault, status: 'unlocked', accounts: unlockedVault.accounts || [],
        currentAccount: unlockedVault.currentAccount || null, dveVaults: [], error: null,
      });
      setStatus('unlocked');
      setError(null);
    } catch (err: any) {
      console.error('Failed to unlock vault:', err);
      setError('Incorrect password');
      updateVaultSession({ error: 'Incorrect password' });
      setStatus('locked');
      throw err;
    }
  }, []);

  const lockVault = useCallback(() => {
    setVault(null); setAccounts([]); setCurrentAccount(null); setDVEVaults([]);
    setStatus('locked');
    updateVaultSession({ vault: null, status: 'locked', accounts: [], currentAccount: null, dveVaults: [] });
  }, []);

  const clearVault = useCallback(async () => {
    await nativeStorage.remove(VAULT_STORAGE_KEY);
    setVault(null); setAccounts([]); setCurrentAccount(null); setDVEVaults([]);
    setStatus('no_vault');
    updateVaultSession({ vault: null, status: 'no_vault', accounts: [], currentAccount: null, dveVaults: [], error: null });
  }, []);

  const deriveDVEVault = useCallback(async (dveID: string, dveName: string, teeType: DVEVault['teeType'], index: number): Promise<DVEVault> => {
    if (!vault || status !== 'unlocked') {
      throw new Error('Vault is locked or not initialized');
    }
    const derivationPath = `${DVE_DERIVATION_BASE_PATH}${index}`;
    const dveVault: DVEVault = {
      dveID, dveName,
      vaultAddress: `${derivationPath}_${dveID.substring(0, 8)}`,
      derivationIndex: index, teeType, status: 'offline',
      stakeAmount: 0, reputationScore: 0, capabilities: [], attachedPolicies: [],
      badgeNFTIDs: [], supervisorAgentID: '',
      dveURI: `knirv://dve/${dveID}/${teeType}`,
    };
    setDVEVaults(prev => [...prev, dveVault]);
    return dveVault;
  }, [vault, status]);

  const updateDVEVaultStatus = useCallback((dveID: string, updates: Partial<DVEVault>) => {
    setDVEVaults(prev => {
      const next = prev.map(w => w.dveID === dveID ? { ...w, ...updates } : w);
      updateVaultSession({ dveVaults: next });
      return next;
    });
  }, []);

  const removeDVEVault = useCallback((dveID: string) => {
    setDVEVaults(prev => {
      const next = prev.filter(w => w.dveID !== dveID);
      updateVaultSession({ dveVaults: next });
      return next;
    });
  }, []);

  const signTransaction = useCallback(async (tx: any) => {
    if (!vault || status !== 'unlocked') {
      throw new Error('Vault is locked or not initialized');
    }
    return vault.signTransaction(tx);
  }, [vault, status]);

  return {
    vault, status, accounts, currentAccount, dveVaults, error,
    createVault, importVault, unlockVault, lockVault, clearVault,
    deriveDVEVault, updateDVEVaultStatus, removeDVEVault, signTransaction,
  };
};

import { Capacitor } from '@capacitor/core';
import { nativeStorage } from './nativeStorage';

export type StorageScope = 'local' | 'session';

function getStorage(scope: StorageScope): Storage | null {
  if (typeof window === 'undefined') { return null; }
  try {
    return scope === 'local' ? window.localStorage : window.sessionStorage;
  } catch { return null; }
}

const sessionMap = new Map<string, string>();

export function getSessionMap(): Map<string, string> {
  return sessionMap;
}

export function readStorageItem(key: string, scope: StorageScope = 'local') {
  return getStorage(scope)?.getItem(key) ?? null;
}

export function writeStorageItem(key: string, value: string, scope: StorageScope = 'local') {
  getStorage(scope)?.setItem(key, value);
}

export function removeStorageItem(key: string, scope: StorageScope = 'local') {
  getStorage(scope)?.removeItem(key);
}

export function readBooleanStorage(key: string, defaultValue: boolean, scope: StorageScope = 'local') {
  const stored = readStorageItem(key, scope);
  return stored === null ? defaultValue : stored === 'true';
}

export async function readStorageItemAsync(key: string, scope: StorageScope = 'local', useNative = Capacitor.isNativePlatform()): Promise<string | null> {
  if (useNative) {
    if (scope === 'session') return sessionMap.get(key) ?? null;
    return nativeStorage.get(key);
  }
  return readStorageItem(key, scope);
}

export async function writeStorageItemAsync(key: string, value: string, scope: StorageScope = 'local', useNative = Capacitor.isNativePlatform()): Promise<void> {
  if (useNative) {
    if (scope === 'session') { sessionMap.set(key, value); return; }
    await nativeStorage.set(key, value);
  } else {
    writeStorageItem(key, value, scope);
  }
}

export async function removeStorageItemAsync(key: string, scope: StorageScope = 'local', useNative = Capacitor.isNativePlatform()): Promise<void> {
  if (useNative) {
    if (scope === 'session') { sessionMap.delete(key); return; }
    await nativeStorage.remove(key);
  } else {
    removeStorageItem(key, scope);
  }
}

export function canUseBrowserApis() {
  return typeof window !== 'undefined' && typeof navigator !== 'undefined';
}

export function hasSecureContext() {
  return canUseBrowserApis() && window.isSecureContext;
}

export function hasCameraSupport() {
  return canUseBrowserApis() && !!navigator.mediaDevices?.getUserMedia;
}

import { Capacitor } from '@capacitor/core';
import { readStorageItem, removeStorageItem, writeStorageItem, getSessionMap } from './browserStorage';

export interface VaultHandoffPayload {
  origin: string;
  message: string;
  createdAt: number;
  autoOpenVault: boolean;
}

const VAULT_HANDOFF_KEY = 'knirv.vault.handoff';

function getInMemoryHandoff(): VaultHandoffPayload | null {
  const raw = getSessionMap().get(VAULT_HANDOFF_KEY);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as VaultHandoffPayload;
  } catch { return null; }
}

function setInMemoryHandoff(payload: VaultHandoffPayload) {
  getSessionMap().set(VAULT_HANDOFF_KEY, JSON.stringify(payload));
}

function removeInMemoryHandoff() {
  getSessionMap().delete(VAULT_HANDOFF_KEY);
}

export function saveVaultHandoff(payload: VaultHandoffPayload) {
  if (Capacitor.isNativePlatform()) {
    setInMemoryHandoff(payload);
  } else {
    writeStorageItem(VAULT_HANDOFF_KEY, JSON.stringify(payload), 'session');
  }
}

export function readVaultHandoff() {
  if (Capacitor.isNativePlatform()) {
    return getInMemoryHandoff();
  }
  const raw = readStorageItem(VAULT_HANDOFF_KEY, 'session');
  if (!raw) { return null; }
  try {
    return JSON.parse(raw) as VaultHandoffPayload;
  } catch { return null; }
}

export function clearVaultHandoff() {
  if (Capacitor.isNativePlatform()) {
    removeInMemoryHandoff();
  } else {
    removeStorageItem(VAULT_HANDOFF_KEY, 'session');
  }
}

